using System.Numerics;
namespace Zuzel;

public sealed partial class ZuzelForm
{
    OnlineClient? online;RoomState? roomState;int lastEpoch=-1;float onlineAlpha=1;
    public int TestOnline(string reportPath){online=new OnlineClient(bindings.Server,9050,"Kontrola EXE",CompetitionMode.Individual);online.StateReceived+=ReceiveRoom;var watch=System.Diagnostics.Stopwatch.StartNew();int snapshots=0;bool sentReady=false,moved=false;float startX=0;online.StateReceived+=s=>snapshots++;
        while(watch.Elapsed.TotalSeconds<18&&!online.Failed){online.Poll();if(roomState!=null){if(roomState.Phase==RoomPhase.Lobby&&!sentReady){online.Ready();sentReady=true;startX=roomState.Riders[roomState.Slot].X;}online.SendInput(roomState.Phase==RoomPhase.Racing?new(1,0):default);if(roomState.Phase==RoomPhase.Racing&&roomState.Riders[roomState.Slot].X<startX-15){moved=true;break;}}Thread.Sleep(5);}
        onlineAlpha=1;using(var bmp=new Bitmap(1920,1080)){using(var g=Graphics.FromImage(bmp))Render(g,bmp.Width,bmp.Height);bmp.Save(Path.ChangeExtension(reportPath,"png"));}File.WriteAllText(reportPath,$"server={bindings.Server}:9050\nroom={roomState?.Room}\nslot={roomState?.Slot+1}\nsnapshots={snapshots}\nready={sentReady}\nmotorcycle_moved={moved}\nphase={roomState?.Phase}\nping_ms={online.Ping}\nstatus={online.Status}\n");online.Dispose();online=null;return moved?0:1;
    }
    void ConnectOnline(){using var dialog=new ConnectDialog(bindings.Nickname,bindings.Server,bindings.Mode);if(dialog.ShowDialog(this)!=DialogResult.OK)return;bindings.Nickname=Wire.CleanName(dialog.Nickname);bindings.Server=dialog.Host;bindings.Save();keyboard.Clear();try{online=new OnlineClient(dialog.Host,9050,bindings.Nickname,bindings.Mode);roomState=null;lastEpoch=-1;scene=Scene.OnlineLobby;online.StateReceived+=ReceiveRoom;}catch(Exception e){online?.Dispose();online=null;MessageBox.Show(this,"Nie można połączyć z serwerem: "+e.Message,"Żużel Online");scene=Scene.Menu;}}
    void LeaveOnline(){online?.Dispose();online=null;roomState=null;lastEpoch=-1;keyboard.Clear();race.Reset();tournament.Start(bindings.Mode);scene=Scene.Menu;audio.Update(race,false,bindings.Muted);}
    void ReadyOnline(){if(roomState==null)return;online?.Ready(!roomState.Ready[roomState.Slot]);}
    void ReceiveRoom(RoomState s){bool changed=lastEpoch!=s.Epoch;roomState=s;lastEpoch=s.Epoch;tournament.ApplyNetwork(s);race.Time=s.Time;countdown=s.Remaining;race.Results.Clear();if(s.Phase is RoomPhase.Results or RoomPhase.Finished)race.Results.AddRange(s.Order);for(int i=0;i<4;i++){Wire.Apply(race.Riders[i],s.Riders[i]);if(changed){race.Riders[i].PreviousPosition=race.Riders[i].Pos;race.Riders[i].PreviousHeading=race.Riders[i].Heading;}}
        if(changed&&s.Phase is RoomPhase.Countdown or RoomPhase.Lobby){dust.Clear();pendingSkids.Clear();using(var g=Graphics.FromImage(skids))g.Clear(Color.Transparent);trackCache?.Dispose();trackCache=null;}
        scene=s.Phase switch{RoomPhase.Lobby=>Scene.OnlineLobby,RoomPhase.Countdown=>Scene.Countdown,RoomPhase.Racing=>Scene.Race,_=>Scene.Results};
    }
    void TickOnline(float dt){if(online==null)return;online.Poll();if(online.Failed){audio.Update(race,false,bindings.Muted);scene=Scene.OnlineLobby;Invalidate();return;}var keys=bindings.Keys[0];Drive pad=Pads.Read(0);float steer=(Down(keys[2])?1:0)-(Down(keys[1])?1:0);var input=focused&&ActiveForm==this?new Drive(Math.Max(Down(keys[0])?1:0,pad.Gas),Math.Abs(steer)>0?steer:pad.Steer):default;online.SendInput(input);onlineAlpha=online.Interpolation;if(roomState!=null){for(int i=0;i<4;i++)race.Riders[i].Gas=i==roomState.Slot?input.Gas:race.Riders[i].Speed>10?1:0;}
        audio.Update(race,scene is Scene.Race or Scene.Countdown,bindings.Muted);Invalidate();}
    void DrawOnlineLobby(Graphics g,float w,float h){float x=w/2-310,y=h/2-220;Panel(g,x,y,620,440);TextAt(g,"ŻUŻEL ONLINE",titleFont,lime,x+28,y+20);TextAt(g,online?.Status??"Rozłączono",bodyFont,Color.White,x+30,y+78);if(roomState!=null){TextAt(g,$"{(roomState.Mode==CompetitionMode.Team?"DRUŻYNOWY":"INDYWIDUALNY")} · POKÓJ {roomState.Room}",labelFont,dim,x+30,y+115);for(int i=0;i<4;i++){Fill(g,colors[i],x+30,y+150+i*37,4,25);TextAt(g,$"{i+1}. {roomState.Names[i]}{(i==roomState.Slot?" (TY)":"")}",boldFont,colors[i],x+45,y+150+i*37);TextAt(g,roomState.Names[i].StartsWith("AI ")?"wolne miejsce":roomState.Ready[i]?"GOTOWY":"czeka",labelFont,dim,x+450,y+155+i*37);}TextAt(g,"Wszyscy gotowi → start. Wolne miejsca uzupełnia AI.",labelFont,dim,x+30,y+308);}
        if(online is {Failed:false}&&roomState!=null)Button(g,"online-ready",roomState.Ready[roomState.Slot]?"NIEGOTOWY  /  SPACJA":"GOTOWY  /  SPACJA",new(x+30,y+339,560,44),true);Button(g,"online-leave","ROZŁĄCZ  /  ESC",new(x+30,y+397,560,28));}
    bool HandleOnlineKey(Keys key){if(online==null)return false;if(key==Keys.Escape){LeaveOnline();return true;}if(key is Keys.Space or Keys.Enter){ReadyOnline();return true;}if(key is Keys.P or Keys.R){return true;}return false;}
}

sealed class ConnectDialog:Form
{
    readonly TextBox nick,host;public string Nickname=>nick.Text;public string Host=>host.Text.Trim();
    public ConnectDialog(string nickname,string server,CompetitionMode mode){Text="Żużel — połącz z serwerem";ClientSize=new(500,265);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(20,32,26);ForeColor=Color.White;Font=new("Segoe UI",10);Controls.Add(new Label{Text="Twój nick",Location=new(24,20),AutoSize=true});nick=new TextBox{Text=nickname,MaxLength=18,Location=new(24,47),Size=new(448,30)};Controls.Add(nick);Controls.Add(new Label{Text="Serwer",Location=new(24,91),AutoSize=true});host=new TextBox{Text=server,MaxLength=100,Location=new(24,116),Size=new(448,30)};Controls.Add(host);Controls.Add(new Label{Text=$"Tryb: {(mode==CompetitionMode.Team?"drużynowy":"indywidualny")} · pokój dobierany automatycznie",Location=new(24,163),AutoSize=true});var ok=new Button{Text="POŁĄCZ",Location=new(260,206),Size=new(210,36),DialogResult=DialogResult.OK};Controls.Add(ok);var cancel=new Button{Text="ANULUJ",Location=new(24,206),Size=new(210,36),DialogResult=DialogResult.Cancel};Controls.Add(cancel);AcceptButton=ok;CancelButton=cancel;FormClosing+=(_,e)=>{if(DialogResult==DialogResult.OK&&(string.IsNullOrWhiteSpace(host.Text)||host.Text.Any(char.IsWhiteSpace))){e.Cancel=true;MessageBox.Show(this,"Wpisz adres serwera bez spacji.");}};}
}
